// Generates app/lib/features/tools/hub/hub_copy.g.dart from the React sources the Tools hub tiles read:
//   scripts/i18n/feature37-copy.json   (sfg_home_title, sfg_tool_desc)
//   scripts/i18n/followup36-copy.json  (names_country)
//   src/data/play-together/tile.ts     (PLAY_TILE_TEXT, PLAY_CONTENT_LANGUAGES)
//   src/data/kid-exercises/tile.ts     (KIDEX_TILE_TEXT, KIDEX_CONTENT_LANGUAGES)
// Run from the repository root:  node app/test/features/tools/tool/gen_hub_copy.mjs
// (app/test/features/tools/hub/hub_copy_test.dart fails when the generated file drifts from these sources.)
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');
const json = (p) => JSON.parse(read(p));

const dartString = (s) => JSON.stringify(s).replace(/\$/g, '\\$');

function tsConst(file, name, open, close) {
  const src = read(file);
  const start = src.indexOf(`export const ${name}`);
  if (start < 0) throw new Error(`${name} not found in ${file}`);
  const eq = src.indexOf('=', start);
  const from = src.indexOf(open, eq);
  let depth = 0;
  for (let i = from; i < src.length; i++) {
    if (src[i] === open) depth++;
    else if (src[i] === close && --depth === 0) return (0, eval)(`(${src.slice(from, i + 1)})`);
  }
  throw new Error(`unterminated ${name}`);
}

function table(name, doc, langs, keys) {
  const lines = [`/// ${doc}`, `const Map<String, Map<String, String>> ${name} = {`];
  for (const [lang, values] of Object.entries(langs)) {
    const picked = keys.filter((k) => typeof values[k] === 'string');
    if (!picked.length) continue;
    lines.push(`  '${lang}': {`);
    for (const k of picked) lines.push(`    '${k}': ${dartString(values[k])},`);
    lines.push('  },');
  }
  lines.push('};', '');
  return lines.join('\n');
}

function tileTable(name, doc, record) {
  const lines = [`/// ${doc}`, `const Map<String, ({String name, String description})> ${name} = {`];
  for (const [lang, v] of Object.entries(record)) {
    lines.push(`  '${lang}': (name: ${dartString(v.name)}, description: ${dartString(v.description)}),`);
  }
  lines.push('};', '');
  return lines.join('\n');
}

const list = (name, doc, values) => `/// ${doc}\nconst List<String> ${name} = [${values.map((v) => `'${v}'`).join(', ')}];\n`;

const out = [
  '// Ported from: scripts/i18n/feature37-copy.json, scripts/i18n/followup36-copy.json, src/data/play-together/tile.ts,',
  '//              src/data/kid-exercises/tile.ts (the keys the Tools hub tiles use)',
  '// GENERATED by app/test/features/tools/tool/gen_hub_copy.mjs. Do not edit by hand.',
  '// ignore_for_file: prefer_single_quotes, lines_longer_than_80_chars',
  '',
  table('kHubFeature37Copy', '`feature37Text` keys of the hub (solid food guide tile).', json('scripts/i18n/feature37-copy.json').languages, ['sfg_home_title', 'sfg_tool_desc']),
  table('kHubFollowupCopy', '`followupText` keys of the hub (baby names tile description).', json('scripts/i18n/followup36-copy.json').languages, ['names_country']),
  tileTable('kPlayTileText', '`PLAY_TILE_TEXT`.', tsConst('src/data/play-together/tile.ts', 'PLAY_TILE_TEXT', '{', '}')),
  list('kPlayContentLanguages', '`PLAY_CONTENT_LANGUAGES`.', tsConst('src/data/play-together/tile.ts', 'PLAY_CONTENT_LANGUAGES', '[', ']')),
  tileTable('kKidExTileText', '`KIDEX_TILE_TEXT`.', tsConst('src/data/kid-exercises/tile.ts', 'KIDEX_TILE_TEXT', '{', '}')),
  list('kKidExContentLanguages', '`KIDEX_CONTENT_LANGUAGES`.', tsConst('src/data/kid-exercises/tile.ts', 'KIDEX_CONTENT_LANGUAGES', '[', ']')),
].join('\n');

const target = path.join(root, 'app/lib/features/tools/hub/hub_copy.g.dart');
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, out.replace(/\n+$/, '\n'));
console.log(`wrote ${path.relative(root, target)}`);
